SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 보더콜리의 지루함 줄이는 놀이 5가지',76,TIMESTAMP '2026-07-20 11:43:46',TIMESTAMP '2026-07-20 11:43:46',9,TO_CLOB('<h2>똑똑한 반려견에게는 두뇌 활동도 필요해요</h2><p>노즈워크, 간단한 트릭 연습, 숨은 장난감 찾기를 짧게 나누어 진행해 보세요.</p><p>한 번에 오래 하기보다 매일 꾸준히 하는 것이 좋습니다.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 코리안숏헤어, 실내 생활 환경 만들기',143,TIMESTAMP '2026-07-28 11:43:46',TIMESTAMP '2026-07-28 11:43:46',14,TO_CLOB('<h2>고양이가 편안한 집은 높은 공간에서 시작돼요</h2><p>캣타워나 선반처럼 안전하게 올라갈 수 있는 공간과 숨을 곳을 마련해 주세요.</p><p>화장실은 조용한 곳에 두고 매일 청결하게 관리하는 것이 좋습니다.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 먼치킨 체형에 맞는 생활 안전 수칙',84,TIMESTAMP '2026-07-22 11:43:46',TIMESTAMP '2026-07-22 11:43:46',16,TO_CLOB('<h2>낮은 높이의 계단과 미끄럼 방지가 중요해요</h2><p>소파와 침대 주변에는 반려동물 계단을 두고, 자주 뛰어내리는 곳에는 미끄럼 방지 매트를 깔아 주세요.</p><p>걷는 모습이 평소와 다르다면 빠르게 병원에 문의하세요.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 러시안블루와 조용한 교감 시간',67,TIMESTAMP '2026-07-17 11:43:46',TIMESTAMP '2026-07-17 11:43:46',18,TO_CLOB('<h2>낯선 환경에서는 먼저 기다려 주세요</h2><p>고양이가 스스로 다가올 때까지 낮은 목소리로 말을 걸고, 짧은 놀이로 관계를 만들어 보세요.</p><p>억지로 안거나 숨는 공간을 막는 행동은 피해주세요.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 도마뱀 사육장 온도와 습도 체크',58,TIMESTAMP '2026-07-25 11:43:46',TIMESTAMP '2026-07-25 11:43:46',22,TO_CLOB('<h2>종마다 다른 적정 환경을 먼저 확인하세요</h2><p>온도계와 습도계를 사육장 양쪽에 설치하면 환경 변화를 더 쉽게 확인할 수 있습니다.</p><p>먹이 섭취량이나 탈피 상태가 달라질 때는 사육 환경을 함께 점검해 주세요.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 거북이 수질 관리와 일광욕 공간',46,TIMESTAMP '2026-07-18 11:43:46',TIMESTAMP '2026-07-18 11:43:46',23,TO_CLOB('<h2>깨끗한 물과 쉴 수 있는 육지 공간을 함께</h2><p>먹이 찌꺼기는 바로 제거하고, 여과기 상태와 물 온도를 정기적으로 확인해 주세요.</p><p>종에 맞는 UVB 조명과 안전한 일광욕 공간도 필요합니다.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 햄스터 케이지 청소 주기와 방법',112,TIMESTAMP '2026-07-26 11:43:46',TIMESTAMP '2026-07-26 11:43:46',29,TO_CLOB('<h2>집 전체를 한 번에 바꾸지 않아도 돼요</h2><p>매일 젖은 깔짚과 먹이 찌꺼기를 제거하고, 전체 청소는 케이지 상태에 맞춰 진행하세요.</p><p>기존 둥지 재료를 일부 남겨두면 환경 변화 스트레스를 줄이는 데 도움이 됩니다.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 토끼가 먹으면 안 되는 음식 정리',91,TIMESTAMP '2026-07-23 11:43:46',TIMESTAMP '2026-07-23 11:43:46',30,TO_CLOB('<h2>건초는 기본, 간식은 소량만</h2><p>토끼는 충분한 양의 건초와 깨끗한 물이 필요합니다. 새로운 채소는 아주 적은 양부터 반응을 살펴보며 급여하세요.</p><p>식욕이 줄거나 배변량이 달라졌다면 빠른 진료가 필요할 수 있습니다.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
SELECT
SEQ_BOARD.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'admin'),'INFO','[펫도감 더미] 친칠라 모래목욕, 이렇게 준비하세요',52,TIMESTAMP '2026-07-16 11:43:46',TIMESTAMP '2026-07-16 11:43:46',31,TO_CLOB('<h2>친칠라 전용 모래를 짧은 시간 제공해요</h2><p>습기에 약한 친칠라는 물목욕 대신 전용 모래목욕이 필요합니다.</p><p>모래가 더러워지면 교체하고, 목욕통은 사용 후 치워두어 과도한 목욕을 예방해 주세요.</p>')
FROM DUAL;

INSERT INTO BOARD (BOARD_ID,MEMBER_ID,BOARD_TYPE,TITLE,HIT,CREATED_AT,UPDATED_AT,ANIMAL_ID,CONTENT)
